mapper.select:
SELECT b.brxx_id AS id, b.brxx_tmh AS barcode, b.brbh AS patientId, b.brxm AS name, b.brxb AS sexCode, CASE b.brxb WHEN 1 THEN '男' WHEN 2 THEN '女' ELSE '' END AS sex, b.brnl AS age, b.nllx AS ageUnit, b.brlb AS category, b.syqk AS urgency, b.ksdm AS dept, b.ksdm AS ward, b.brch AS bedNo, b.syh AS sampleNo, CASE b.bbzl WHEN 1 THEN '血清' WHEN 2 THEN '血浆' WHEN 3 THEN '尿液' WHEN 4 THEN '粪便' WHEN 5 THEN '脑脊液' WHEN 6 THEN '胸腹水' WHEN 7 THEN '其它' ELSE CAST(b.bbzl AS CHAR) END AS sampleType, b.bbzl AS sampleTypeCode, b.ybzt AS status, DATE_FORMAT(b.jyrq, '%Y-%m-%d %H:%i') AS applicationTime, DATE_FORMAT(b.jyrq, '%Y-%m-%d %H:%i') AS submitDate, DATE_FORMAT(b.srrq, '%Y-%m-%d %H:%i') AS samplingTime, DATE_FORMAT(b.jyrq, '%Y-%m-%d %H:%i') AS verificationTime, b.czy AS entryPerson, DATE_FORMAT(b.jyrq, '%Y-%m-%d %H:%i') AS inspectionTime, b.jyys AS inspectDoctor, b.jyys AS inspectingPhysician, DATE_FORMAT(b.shrq, '%Y-%m-%d %H:%i') AS reviewTime, b.shys AS auditDoctor, b.shys AS reviewingPhysician, b.sjys AS doctor, b.lczd AS diagnosis, b.bz AS remarks, b.bz2 AS additionalRemarks, b.tjdw AS physicalExamUnit, b.zjhm AS idNumber, b.lxfs AS contactInfo, b.bbxt AS sampleMorphology, b.czy AS entryPerson, b.dycs AS printCount, DATE_FORMAT(b.bgrq, '%Y-%m-%d %H:%i') AS printTime FROM bgxt_brxx b WHERE b.brxx_id IN
#{id}
ORDER BY b.syh

mapper.update:
UPDATE bgxt_brxx SET brxx_tmh=#{brxxTmh}, brbh=#{brbh}, brxm=#{brxm}, brxb=#{brxb}, brnl=#{brnl},
nllx=#{nllx}, brlb=#{brlb}, syh=#{syh}, syqk=#{syqk}, ksdm=#{ksdm}, brch=#{brch},
bbzl=#{bbzl}, lczd=#{lczd}, sb_djid=#{sbDjid} WHERE brxx_id=#{brxxId}

mapper.insert:
INSERT INTO bgxt_brxx_log (brxx_tmh, brbh, brxm, brxb, brnl, nllx, brlb, syqk, ksdm, brch, syh, bbzl, ybzt, jyrq, sfbz, bz, qxshczy, qxshrq)
SELECT brxx_tmh, brbh, brxm, brxb, brnl, nllx, brlb, syqk, ksdm, brch, syh, bbzl, ybzt, jyrq, sfbz, bz, #{czydm}, NOW()
FROM bgxt_brxx WHERE brxx_id = #{brxxId}

mapper.select:
SELECT b.brxx_id, b.brxm, b.brxb, b.brnl, b.brlb, b.syqk, b.syh, b.ybzt,
b.jyrq, b.shrq, b.brxx_tmh, b.brch, b.ksdm, b.bbzl, b.yczt, b.sfbz,
s.sbmc, k.ksmc
FROM bgxt_brxx b
LEFT JOIN sys_sbdjb s ON b.sb_djid = s.sb_djid
LEFT JOIN sys_kssz k ON b.ksdm = k.ksdm WHERE 1=1

 AND b.sb_djid = #{sbDjid}


 AND DATE(b.jyrq) = #{date}


 AND b.brlb = #{brlb}

ORDER BY b.syh DESC LIMIT 500

SELECT b.brxx_id AS id, b.brxx_tmh AS barcode, b.jyrq AS receiveTime, b.brxm AS patientName, CASE b.brxb WHEN 1 THEN '男' WHEN 2 THEN '女' ELSE '' END AS sex, b.brnl AS age, b.ksdm AS department, IFNULL(b.brch, '') AS bedNo, CASE b.brlb WHEN 1 THEN '门诊' WHEN 2 THEN '住院' WHEN 3 THEN '体检' WHEN 4 THEN '其他' WHEN 5 THEN '科研' ELSE '' END AS patientCategory, '' AS workGroup, '' AS receiver FROM bgxt_brxx b WHERE 1=1
AND DATE(b.jyrq) >= DATE(#{startDate})
AND DATE(b.jyrq) <= DATE(#{endDate})
AND CASE #{patientType} WHEN '门诊病人' THEN b.brlb=1 WHEN '住院病人' THEN b.brlb=2 WHEN '体检人员' THEN b.brlb=3 WHEN '其他病人' THEN b.brlb=4 WHEN '科研人员' THEN b.brlb=5 END
AND b.ksdm = #{department}
ORDER BY b.jyrq DESC LIMIT #{limit} OFFSET #{offset}

SELECT b.brxx_id, b.brxm, b.brxb, b.brnl, b.brlb, b.syh, b.ybzt,
b.brxx_tmh, b.ksdm, b.jyrq
FROM bgxt_brxx b WHERE 1=1

 AND b.brxm LIKE CONCAT('%', #{brxm}, '%')


 AND b.brxx_tmh = #{brxxTmh}


 AND b.syh = #{syh}


 AND b.ksdm = #{ksdm}


 AND b.brlb = #{brlb}


 AND b.ybzt IN #{y}


 AND b.sb_djid = #{sbDjid}


 AND b.jyrq >= #{beginDate}


 AND b.jyrq <= CONCAT(#{endDate}, ' 23:59:59')

ORDER BY b.syh DESC LIMIT 500

SELECT DISTINCT b.brxx_id, b.brxm, b.brxb, b.brnl, b.brlb, b.syh, b.ybzt, b.jyrq,
b.brxx_tmh, b.ksdm, b.bbzl, b.shrq, s.sbmc, k.ksmc, b.bgbh, b.bgmc
FROM bgxt_brxx b
LEFT JOIN sys_sbdjb s ON b.sb_djid = s.sb_djid
LEFT JOIN sys_kssz k ON b.ksdm = k.ksdm
WHERE b.ybzt >= 0

 AND COALESCE(b.shrq, b.jyrq) >= #{beginDate}


  AND COALESCE(b.shrq, b.jyrq) <= CONCAT(#{endDate}, ' 23:59:59')


 AND b.brlb = #{brlb}


 AND b.ksdm = #{ksdm}


 AND b.sb_djid = #{sbDjid}

ORDER BY b.syh

mapper.insert:
INSERT INTO zk_nyzkjg (zkpid, zkxmid, yssj, yhsj, syrq, sybz, skbz)
SELECT NULL, xmid, jyjg, jyjg, NOW(), 1, 0
FROM bgxt_jyjg WHERE brxx_id = #{brxxId}

mapper.select:
SELECT DISTINCT b.brxx_id, b.brxm, b.brxb, b.brnl, b.brlb, b.syh, b.ybzt, b.jyrq,
b.brxx_tmh, b.ksdm, b.bbzl, b.shrq, s.sbmc, k.ksmc, b.bgbh, b.bgmc,
b.brch, b.brbh, b.lczd
FROM bgxt_brxx b
LEFT JOIN sys_sbdjb s ON b.sb_djid = s.sb_djid
LEFT JOIN sys_kssz k ON b.ksdm = k.ksdm
WHERE b.ybzt >= 0

 AND COALESCE(b.shrq, b.jyrq) >= #{beginDate}


  AND COALESCE(b.shrq, b.jyrq) <= CONCAT(#{endDate}, ' 23:59:59')


 AND b.brlb = #{brlb}


 AND b.ksdm = #{ksdm}


 AND b.ksdm = #{tjdw}


 AND b.sb_djid = #{sbDjid}

ORDER BY b.syh
